// Publish dates follow Eastern time, so a post opens at midnight in Charleston, not at midnight UTC.
const PUBLISH_TZ = "America/New_York";
const publishDay = (now: Date): string => now.toLocaleDateString("en-CA", { timeZone: PUBLISH_TZ });

// A post is live once its publish date has arrived and it is not a draft.
// Future-dated posts render a scheduled page until their publish date, so a series can be prepared in advance.
export const isLive = (post: BlogPost, now: Date = new Date()): boolean =>
    !post.draft && post.date <= publishDay(now);

export const livePosts = (now: Date = new Date()): BlogPost[] => blogPosts.filter(p => isLive(p, now));

export const scheduledPosts = (now: Date = new Date()): BlogPost[] =>
    blogPosts.filter(p => !p.draft && !isLive(p, now)).sort((a, b) => a.date.localeCompare(b.date));

// Card-level fields only. Client components receive these, never full post content,
// so a scheduled post's text cannot be read from the page source before its date.
export type PostSummary = Pick<BlogPost, "id" | "title" | "date" | "excerpt" | "category" | "readTime">;

export const summarize = (p: BlogPost): PostSummary => ({
    id: p.id,
    title: p.title,
    date: p.date,
    excerpt: p.excerpt,
    category: p.category,
    readTime: p.readTime,
});
